import hashlib, json, os, sys
root, venv, data, adapter = sys.argv[1], sys.argv[2], json.loads(sys.argv[3]), sys.argv[4]
CODE = ('.py', '.pyx', '.pxd', '.pth', '.so', '.c', '.cc', '.cpp', '.h', '.sh', '.cfg', '.ini', '.toml', '.yaml', '.yml', '.ipynb')
def digest(base, keep):
    if not os.path.isdir(base): return None
    total, count = hashlib.sha256(), 0
    for d, dirs, files in os.walk(base):
        dirs.sort()
        for name in sorted(files):
            path = os.path.join(d, name); rel = os.path.relpath(path, base)
            if os.path.islink(path):
                total.update(b'L' + rel.encode() + b'\0' + os.readlink(path).encode() + b'\n'); count += 1; continue
            if not keep(rel): continue
            h = hashlib.sha256()
            with open(path, 'rb') as handle:
                for chunk in iter(lambda: handle.read(1 << 20), b''): h.update(chunk)
            total.update(rel.encode() + b'\0' + h.hexdigest().encode() + b'\n'); count += 1
    return total.hexdigest() + ':' + str(count)
def code(rel):
    parts = rel.split(os.sep)
    if rel.endswith('.pyc'): return '__pycache__' not in parts
    return rel.endswith(CODE) or any(rel == p or rel.startswith(p.rstrip('/') + '/') for p in data)
print(json.dumps({'workRepo': digest(root, code), 'venv': digest(venv, lambda rel: '__pycache__' not in rel.split(os.sep)), 'adapter': digest(adapter, lambda rel: True)}))

import difflib, hashlib, json, os, sys
base, work, cap, adapter_path, adapter_text = sys.argv[1], sys.argv[2], int(sys.argv[3]), sys.argv[4], sys.argv[5]
def files(root):
    out = {}
    for d, dirs, names in os.walk(root):
        dirs[:] = sorted(x for x in dirs if x not in ('__pycache__', '.git'))
        for name in sorted(names):
            path = os.path.join(d, name)
            if os.path.islink(path) or name.endswith('.pyc'): continue
            out[os.path.relpath(path, root)] = path
    return out
a, b = files(base), files(work)
def read(path):
    with open(path, 'rb') as handle: return handle.read()
pairs = [(rel, read(a[rel]) if rel in a else None, read(b[rel]) if rel in b else None) for rel in sorted(set(a) | set(b))]
if adapter_path:
    pairs.append(('adapter/' + os.path.basename(adapter_path), adapter_text.encode(), read(adapter_path) if os.path.isfile(adapter_path) else None))
CODE = ('.py', '.pyx', '.pxd', '.pth', '.so', '.c', '.cc', '.cpp', '.h', '.sh', '.cfg', '.ini', '.toml', '.yaml', '.yml', '.json', '.ipynb', '.txt')
changed, chunks = [], []
for rel, old, new in pairs:
    if old == new: continue
    changed.append({'path': rel, 'change': 'added' if old is None else 'removed' if new is None else 'changed', 'code': rel.endswith(CODE)})
    try:
        lines = lambda raw: [] if raw is None else raw.decode('utf-8').splitlines(keepends=True)
        chunks.append(''.join(difflib.unified_diff(lines(old), lines(new), 'a/' + rel, 'b/' + rel)))
    except UnicodeDecodeError:
        chunks.append('Binary file ' + rel + ' differs\n')
diff = ''.join(chunks)
print(json.dumps({'changed': changed, 'diff': diff[:cap], 'diffSha256': hashlib.sha256(diff.encode()).hexdigest(), 'diffTruncated': len(diff) > cap}))

